"""Who the server is logged in as, and what that costs (plan T3.2, D12). Docker + Gramps Web.

The README recommends deploying with an **EDITOR** account, and two of the 31 tools cannot
work under one: the Gramps Web server itself answers `403 FORBIDDEN` for the import endpoint
and for the bulk delete. That is not a bug to fix here — it is a property of the deployment
this repository recommends, so it has to be a test rather than a sentence someone measured
once. If a future wave adds a third OWNER-only tool, the EDITOR profile is where it shows up.

The second half is the credential that is merely *wrong*. It matters because the failure is
invisible at start-up: the REST client is lazy, so the container comes up, answers the
handshake, lists all its tools, and only fails when something is actually asked of it. A test
that only checked "does it start" would call a server with a dead password healthy.
"""

from __future__ import annotations

from collections.abc import Iterator

import pytest
from harness import tool_contract
from harness.backup_dir import BackupDir
from harness.gramps_instance import (
    EDITOR_PW,
    EDITOR_USER,
    OWNER_PW,
    OWNER_USER,
    ROLE_EDITOR,
    ROLE_OWNER,
    GrampsInstance,
)
from harness.mcp_container import ImageRef, McpContainer, container_name
from harness.rest import GrampsRest
from harness.runid import new_runid

# Needs a live Gramps Web instance, not merely Docker. Declared rather than inferred: the
# required CI leg selects `-m 'e2e and not gramps'`, and a module that forgets this marker
# would drag a whole instance bring-up into the job that is meant to need no services.
pytestmark = pytest.mark.gramps

FORBIDDEN = "403 Client Error: FORBIDDEN"
OWNER_ONLY = ("gramps_import_file", "gramps_delete_all_objects")


@pytest.fixture(scope="module")
def instance() -> Iterator[GrampsInstance]:
    started = GrampsInstance(new_runid())
    started.start()
    assert started.add_user(OWNER_USER, OWNER_PW, ROLE_OWNER)["rc"] == 0
    assert started.add_user(EDITOR_USER, EDITOR_PW, ROLE_EDITOR)["rc"] == 0
    try:
        yield started
    finally:
        started.teardown()


@pytest.fixture(scope="module")
def as_editor(
    instance: GrampsInstance, mcp_image: ImageRef, tmp_path_factory: pytest.TempPathFactory
) -> Iterator[McpContainer]:
    """The recommended deployment, armed: destructive tools on, so the refusal is the server's.

    Without `GRAMPS_ENABLE_DESTRUCTIVE=1` the wipe would not be registered and the test would
    prove the local gate instead of the remote role — the same assertion text, a different and
    much weaker claim.
    """
    backup = BackupDir(tmp_path_factory.mktemp("editor") / "backup")
    backup.reset()
    mcp = McpContainer(
        container_name(instance.runid, "editor"),
        mcp_image.run_reference,
        {
            "GRAMPS_BASE_URL": instance.internal_url,
            "GRAMPS_USERNAME": EDITOR_USER,
            "GRAMPS_PASSWORD": EDITOR_PW,
            "GRAMPS_BACKUP_DIR": "/data",
            "GRAMPS_ENABLE_DESTRUCTIVE": "1",
        },
        network=instance.network,
        mounts=((str(backup.path), "/data"),),
        runid=instance.runid,
    )
    try:
        yield mcp
    finally:
        assert mcp.close() == [], "the MCP container outlived its test"


@pytest.fixture(scope="module")
def populated(as_editor: McpContainer) -> McpContainer:
    """One person, added by the editor. The wipe needs a count to guard against."""
    added = as_editor.call(
        "gramps_add_person", {"first_name": "Rolle", "surname": "Probe", "gender": 1}
    )

    assert not added.is_error, added.text
    return as_editor


def test_an_editor_may_write_to_the_tree(populated: McpContainer, instance: GrampsInstance) -> None:
    """The control. Without it, "403" would be indistinguishable from a broken instance."""
    rest = GrampsRest(instance.url, OWNER_USER, OWNER_PW)

    assert rest.object_counts()["people"] == 1


def test_an_editor_may_export_the_tree(populated: McpContainer) -> None:
    """Export reads; it is the OWNER-only *import* that this pairs with."""
    exported = populated.call(
        "gramps_export_tree", {"filename": "editor-probe.gramps"}, timeout=120
    )

    assert not exported.is_error, exported.text
    assert "/data/editor-probe.gramps" in exported.text


@pytest.mark.parametrize("tool", OWNER_ONLY)
def test_the_server_refuses_the_owner_only_tools_for_an_editor(
    populated: McpContainer, instance: GrampsInstance, tool: str
) -> None:
    """Refused at the far end, by Gramps Web, with a 403 — not by anything in this repository.

    The distinction is the finding: a local guard could be relaxed, a server role cannot, so a
    deployment that follows the README's recommendation simply does not have these two tools.
    """
    rest = GrampsRest(instance.url, OWNER_USER, OWNER_PW)
    arguments = {
        "gramps_import_file": {"filename": "editor-probe.gramps"},
        "gramps_delete_all_objects": {
            "confirm": True,
            "expected_count": sum(rest.object_counts().values()),
        },
    }[tool]

    answer = populated.call(tool, arguments, timeout=120)

    assert answer.is_error is True
    assert FORBIDDEN in answer.text
    assert rest.object_counts()["people"] == 1, "a refusal that changed the tree is not a refusal"


def test_every_tool_an_editor_cannot_use_says_so_in_its_docstring() -> None:
    """D12's live risk, closed: a tool that silently needs OWNER is one the README recommends
    a deployment for that cannot run it. The docstring is the only place a model finds out."""
    served = tool_contract.load()["tools"]

    for tool in OWNER_ONLY:
        assert "OWNER" in served[tool]["description"], f"{tool} never mentions the role it needs"


def test_a_wrong_password_starts_fine_and_fails_on_the_first_call(
    instance: GrampsInstance, mcp_image: ImageRef
) -> None:
    """The lazy client makes a dead credential a *runtime* failure, and this pins that shape.

    Both halves are asserted on purpose: the handshake succeeds and the tool list is complete,
    so "the server is up" says nothing about whether it can reach anything.

    **Measured 2026-08-01, and not what was assumed:** a wrong password is answered by
    `/api/token/` with **403 FORBIDDEN**, not 401. The distinction is not cosmetic — the client
    re-logs in and retries exactly once on 401, so if a bad credential arrived as 401 it would
    burn a second token mint against a 1/second limit to be told the same thing twice. It does
    not, and this test is where that stays true. (The instance already had one surprise of this
    kind: rotating the secret answers 422, not 401.)
    """
    mcp = McpContainer(
        container_name(instance.runid, "badpw"),
        mcp_image.run_reference,
        {
            "GRAMPS_BASE_URL": instance.internal_url,
            "GRAMPS_USERNAME": OWNER_USER,
            "GRAMPS_PASSWORD": OWNER_PW + "-wrong",
        },
        network=instance.network,
        runid=instance.runid,
    )
    try:
        served = tool_contract.from_wire(tool_contract.read_pages(mcp.list_tools))
        answer = mcp.call("gramps_get_object_counts", {}, timeout=90)
    finally:
        assert mcp.close() == [], "the MCP container outlived its test"

    assert len(served) == len(tool_contract.load()["gate_off"])
    assert answer.is_error is True
    assert FORBIDDEN in answer.text
    assert "/api/token/" in answer.text, "the failure is the login, not the endpoint that asked"
